static bool dm_DsDsTproverkau2eSign_eq(const dm_DsDsTproverkau2eSign *x, const dm_DsDsTproverkau2eSign *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsDsTproverkau2eSign_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dm_DsTproverkau2eSign* a = x->vals[e]; dm_DsTproverkau2eSign* b = y->vals[f];
        if (!(dm_DsTproverkau2eSign_eq(a, b))) return false;
    }
    return true;
}


