static int dan_cmp_s(dan_str x, dan_str y) { return strcmp(x, y); }
static int dan_qcmp_s(const void *a, const void *b) { return dan_cmp_s(*(const dan_str *)a, *(const dan_str *)b); }
static dl_Ls *dan_sorted_s(const dl_Ls *l) {
    dl_Ls *r = dl_Ls_from(l->len, l->items);
    qsort(r->items, (size_t)r->len, sizeof(dan_str), dan_qcmp_s);
    return r;
}

static dl_Ls *dan_set_s(const dl_Ls *l) {
    dl_Ls *s = dan_sorted_s(l);
    int64_t k = 0;
    for (int64_t i = 0; i < s->len; i++)
        if (k == 0 || dan_cmp_s(s->items[k - 1], s->items[i]) != 0) s->items[k++] = s->items[i];
        else dan_str_release(s->items[i]);
    s->len = k;
    return s;
}
static bool dan_contains_s(dan_str x, const dl_Ls *l) {
    for (int64_t i = 0; i < l->len; i++) if (dan_cmp_s(l->items[i], x) == 0) return true;
    return false;
}
static dl_Ls *dan_union_s(const dl_Ls *a, const dl_Ls *b) {
    dl_Ls *r = dl_Ls_from(a->len, a->items);
    for (int64_t i = 0; i < b->len; i++) dl_Ls_push(r, b->items[i]);
    return dan_set_s(r);
}
static dl_Ls *dan_intersection_s(const dl_Ls *a, const dl_Ls *b) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t i = 0; i < a->len; i++) if (dan_contains_s(a->items[i], b)) dl_Ls_push(r, a->items[i]);
    return dan_set_s(r);
}
static dl_Ls *dan_difference_s(const dl_Ls *a, const dl_Ls *b) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t i = 0; i < a->len; i++) if (!dan_contains_s(a->items[i], b)) dl_Ls_push(r, a->items[i]);
    return dan_set_s(r);
}
static bool dan_subset_s(const dl_Ls *a, const dl_Ls *b) {
    for (int64_t i = 0; i < a->len; i++) if (!dan_contains_s(a->items[i], b)) return false;
    return true;
}

static int64_t dan_mode_i(const dl_Li *l, int line) {
    dan_need_items_i(l, line);
    dl_Li *s = dan_sorted_i(l);
    int64_t best = s->items[0], best_count = 0;
    for (int64_t i = 0; i < s->len;) {
        int64_t j = i;
        while (j < s->len && s->items[j] == s->items[i]) j++;
        if (j - i > best_count) { best_count = j - i; best = s->items[i]; }
        i = j;
    }
    return best;
}
static dan_rat dan_f_0_r(dan_rat a0, dan_rat a1, dan_rat a2, int line) { (void)line; return dan_rat_div(dan_rat_mul(a1, a2, line), a0, line); }
static double dan_f_1_f(double a0, double a1, double a2, int line) { (void)line; return ((a1 * a2) / a0); }
static dan_rat dan_f_2_r(dan_rat a0, dan_rat a1, int line) { (void)line; return dan_rat_div(dan_rat_mul(a0, a1, line), dan_rat_from_int(100, line), line); }
static double dan_f_3_f(double a0, double a1, int line) { (void)line; return ((a0 * a1) / 100.0); }
static dan_rat dan_f_4_r(dan_rat a0, dan_rat a1, int line) { (void)line; return dan_rat_div(dan_rat_mul(a0, dan_rat_from_int(100, line), line), a1, line); }
static double dan_f_5_f(double a0, double a1, int line) { (void)line; return ((a0 * 100.0) / a1); }
static dan_rat dan_f_6_r(dan_rat a0, dan_rat a1, int line) { (void)line; return dan_rat_div(dan_rat_mul(a0, dan_rat_from_int(100, line), line), a1, line); }
