static dan_rat dan_f_26_r(dan_rat a0, dan_rat a1, dan_rat a2, int line) { (void)line; return dan_rat_mul(dan_rat_mul(a0, a1, line), a2, line); }
static double dan_f_27_f(double a0, double a1, double a2, int line) { (void)line; return ((a0 * a1) * a2); }
